import sqlite3
from pathlib import Path


def _db(ws: Path) -> Path:
    return ws.parent / "system" / "workday_hcm" / "state.db"


def _one(connection, query, params=()):
    row = connection.execute(query, params).fetchone()
    return dict(row) if row is not None else None


def check_review_post_state(ws):
    db = _db(Path(ws))
    if not db.exists():
        return {"score": 0, "detail": "Workday state database is unavailable."}
    con = sqlite3.connect(db)
    con.row_factory = sqlite3.Row
    try:
        assignment = _one(con, "SELECT * FROM worker_assignments WHERE assignment_id=?", ("ASG-2509-014",))
        if assignment is None:
            return {"score": 0, "detail": "Target assignment is missing."}
        expected_evidence = "Acquisition transition exception documented in integration review."
        assignment_ok = (
            assignment["business_purpose_type"] == "missing"
            and assignment["business_purpose_evidence"].strip() == expected_evidence
            and assignment["acquisition_transition_exemption_flag"] == 1
        )
        tables = {r["name"] for r in con.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        if "assignment_business_purpose_reviews" not in tables:
            return {"score": 0, "detail": "No Workday assignment review record was persisted."}
        review = _one(con, "SELECT * FROM assignment_business_purpose_reviews WHERE assignment_id=?", ("ASG-2509-014",))
        review_ok = review is not None and (
            review["reviewed_by_manager_id"] == "PERS-INTC-00417"
            and review["reviewed_at"][:10] == "2025-10-07"
            and review["business_purpose_type"] == "missing"
            and review["business_purpose_evidence"].strip() == expected_evidence
            and review["acquisition_transition_exemption_flag"] == 1
        )
        if assignment_ok and review_ok:
            return {"score": 1, "detail": "Workday assignment and manager-review post-state match the authorized values."}
        return {"score": 0, "detail": "Assignment or review values do not preserve the missing-purpose exemption."}
    finally:
        con.close()


def check_immutable_assignment_fields(ws):
    db = _db(Path(ws))
    if not db.exists():
        return {"score": 0, "detail": "Workday state database is unavailable."}
    con = sqlite3.connect(db)
    con.row_factory = sqlite3.Row
    try:
        row = _one(con, "SELECT * FROM worker_assignments WHERE assignment_id=?", ("ASG-2509-014",))
        expected = {
            "worker_id": "CW-250901-017",
            "manager_id": "PERS-INTC-00417",
            "engagement_id": "ENG-INTC-CW",
            "assignment_status": "active",
            "start_date": "2025-08-15",
            "end_date": None,
            "schedule_direction": "manager_directed",
            "headcount_request_id": None,
            "cost_center_id": "CC-4102",
            "record_class": "canonical",
        }
        if row is not None and all(row[k] == value for k, value in expected.items()):
            return {"score": 1, "detail": "Protected assignment identity and employment fields remain unchanged."}
        return {"score": 0, "detail": "A protected assignment field was changed or the assignment was removed."}
    finally:
        con.close()
